blocks=re.split(r'(?m)"'^- id: '"',Path('lean/claims.yaml').read_text())[1:];claims=[]
for b in blocks:
 def get(k):
  m=re.search(r'(?m)"'^  '"'+k+r': (.*)"'$'"',b);return m[1] if m else None
 claims.append((get('decl'),get('kind'),get('status'),get('file')))
rc=collections.Counter(r[0] for r in rows);cc=collections.Counter(c[0] for c in claims)
print('ROWS',len(rows),'KINDS',dict(collections.Counter(c[1] for c in claims)),'CLAIMS',len(claims))
