ints=collections.Counter(c[0].split('.')[1] for c in claims if c[2]=='internal');print('INTERNAL MODULES',dict(ints))
labels=set(re.findall(r'"'`([A-Z]:[''^`]+)`'"','\\n'.join(ledger[1753:1836])));found={k:[] for k in labels}
for p in sorted(Path('manuscript/notes').rglob('*.tex')):
 for n,s in enumerate(p.read_text().splitlines(),1):
  for label in re.findall(r'\\\\label\\{(["'^}]+)'"\\}',s):
   if label in labels: found[label].append(f'{p}:{n}: {s.strip()}')
print('SECTION LABEL SEARCH',found)
